values
  ('kb-001', 'هل يجوز أن يرقي الإنسان نفسه؟', 'هل يجوز أن يرقي الإنسان نفسه؟', 'نعم، رقية الإنسان لنفسه مشروعة، وهي أولى من التعلق بالناس، مع التزام القرآن والأدعية الصحيحة.', array['رقية','النفس','ذاتية']::text[], 'الرقية', 'صحيح البخاري 5017؛ صحيح مسلم 2191', 'sunnah', 'صحيح البخاري 5017؛ صحيح مسلم 2191', 'verified', 500, true),
  ('kb-002', 'هل الرقية تغني عن الطبيب؟', 'هل الرقية تغني عن الطبيب؟', 'لا. الرقية دعاء وعبادة، والعلاج الطبي سبب مشروع، ويُجمع بينهما عند الحاجة.', array['طبيب','علاج','دواء']::text[], 'الرقية', 'إرشاد شرعي وصحي عام', 'owner', 'إرشاد شرعي وصحي عام', 'review', 500, false),
  ('kb-003', 'ما ضابط الرقية المشروعة؟', 'ما ضابط الرقية المشروعة؟', 'أن تكون بكلام مفهوم خالٍ من الشرك، مع اعتقاد أن الشفاء من الله لا من الكلمات بذاتها.', array['ضابط','شرك','طلاسم']::text[], 'الرقية', 'صحيح مسلم 2200', 'sunnah', 'صحيح مسلم 2200', 'review', 500, false),
  ('kb-004', 'هل يجوز النفث بعد القراءة؟', 'هل يجوز النفث بعد القراءة؟', 'نعم، ثبت النفث الخفيف في اليدين والمسح على الجسد.', array['نفث','مسح']::text[], 'الرقية', 'صحيح البخاري 5017', 'sunnah', 'صحيح البخاري 5017', 'verified', 500, true),
  ('kb-005', 'هل يجوز تخصيص أعداد لم تثبت؟', 'هل يجوز تخصيص أعداد لم تثبت؟', 'لا يُعتقد لعدد معين فضل خاص بلا دليل، ويجوز التكرار بقدر الحاجة دون ادعاء لزوم.', array['عدد','تكرار']::text[], 'الرقية', 'قاعدة الاتباع في العبادات', 'owner', 'قاعدة الاتباع في العبادات', 'review', 500, false),
  ('kb-006', 'هل العين حق؟', 'هل العين حق؟', 'نعم ثبت ذلك في السنة، لكن لا يجوز جعل كل مرض أو تعطل دليلًا على العين.', array['العين','حق']::text[], 'العين', 'صحيح البخاري 5740؛ صحيح مسلم 2188', 'sunnah', 'صحيح البخاري 5740؛ صحيح مسلم 2188', 'verified', 500, true),
  ('kb-007', 'هل الصداع وحده دليل على العين؟', 'هل الصداع وحده دليل على العين؟', 'لا، الصداع عرض شائع له أسباب كثيرة ويحتاج تقييمًا صحيًا عند الاستمرار.', array['صداع','تشخيص']::text[], 'العين', 'إرشاد سلامة صحي', 'owner', 'إرشاد سلامة صحي', 'review', 500, false),
  ('kb-008', 'هل يجوز اتهام شخص بأنه عائن؟', 'هل يجوز اتهام شخص بأنه عائن؟', 'لا يجوز الاتهام بلا بينة، ولا يعتمد في ذلك على حلم أو شعور أو كلام غير موثوق.', array['اتهام','عائن']::text[], 'العين', 'قواعد حفظ العرض ومنع الظن', 'owner', 'قواعد حفظ العرض ومنع الظن', 'review', 500, false),
  ('kb-009', 'كيف أحصن نفسي من العين؟', 'كيف أحصن نفسي من العين؟', 'بالمحافظة على الصلاة والأذكار والمعوذات والدعاء بالبركة مع التوكل والاعتدال.', array['تحصين']::text[], 'العين', 'أحاديث الأذكار والمعوذات', 'owner', 'أحاديث الأذكار والمعوذات', 'review', 500, false),
  ('kb-010', 'هل كل إعجاب يسبب العين؟', 'هل كل إعجاب يسبب العين؟', 'لا، ولا ينبغي العيش في خوف. المشروع الدعاء بالبركة عند رؤية ما يعجب.', array['إعجاب','بركة']::text[], 'العين', 'موطأ مالك في قصة سهل بن حنيف؛ شروح باب العين', 'sunnah', 'موطأ مالك في قصة سهل بن حنيف؛ شروح باب العين', 'review', 500, false),
