  ('kb-013', 'هل يجوز قطع الأقارب بسبب الشك في حسدهم؟', 'هل يجوز قطع الأقارب بسبب الشك في حسدهم؟', 'لا يُبنى القطع على الظن؛ تضبط الحدود بحسب السلوك الظاهر مع حفظ الحقوق.', array['قطيعة','أقارب']::text[], 'الحسد', 'قواعد صلة الرحم وحسن الظن', 'owner', 'قواعد صلة الرحم وحسن الظن', 'review', 500, false),
  ('kb-014', 'هل الملح أو البيض يكشفان الحسد؟', 'هل الملح أو البيض يكشفان الحسد؟', 'لا توجد طريقة شرعية أو علمية يعتمد عليها لتشخيص الحسد بهذه الأشياء.', array['ملح','بيض']::text[], 'الحسد', 'ضوابط الرقية والسلامة', 'owner', 'ضوابط الرقية والسلامة', 'review', 500, false),
  ('kb-015', 'ما السورة التي فيها الاستعاذة من الحاسد؟', 'ما السورة التي فيها الاستعاذة من الحاسد؟', 'سورة الفلق، وفيها: ومن شر حاسد إذا حسد.', array['الفلق']::text[], 'الحسد', 'سورة الفلق 5', 'quran', 'سورة الفلق 5', 'verified', 500, true),
