  ('kb-017', 'ما آيات إبطال السحر؟', 'ما آيات إبطال السحر؟', 'منها الأعراف 117–122، يونس 81–82، وطه 68–70.', array['آيات','السحر']::text[], 'السحر', 'القرآن الكريم', 'quran', 'القرآن الكريم', 'review', 500, false),
