  ('kb-019', 'ماذا أفعل عند العثور على مادة مجهولة؟', 'ماذا أفعل عند العثور على مادة مجهولة؟', 'لا تلمسها أو تشمها، أبعد الأطفال، وتواصل مع الجهة المختصة إذا كانت خطرة أو مرتبطة بجريمة.', array['مادة','مجهولة']::text[], 'السحر', 'إرشاد سلامة عام', 'owner', 'إرشاد سلامة عام', 'review', 500, false),
