  ('kb-037', 'ماذا أقول عند الألم؟', 'ماذا أقول عند الألم؟', 'قل بسم الله ثلاثًا، ثم أعوذ بعزة الله وقدرته من شر ما أجد وأحاذر سبع مرات.', array['ألم']::text[], 'الدعاء', 'صحيح مسلم 2202', 'sunnah', 'صحيح مسلم 2202', 'verified', 500, true),
