do $$
declare
  lesson_count integer;
  question_count integer;
  approved_count integer;
begin
  select count(*) into lesson_count from public.academy_lessons;
  select count(*) into question_count from public.academy_questions;
  select count(*) into approved_count from public.ai_knowledge where active = true and trust_tier <> 'review';
  if lesson_count < 310 then raise exception 'V92_LESSON_SEED_INCOMPLETE: %', lesson_count; end if;
  if question_count < 600 then raise exception 'V92_QUESTION_SEED_INCOMPLETE: %', question_count; end if;
  if approved_count < 16 then raise exception 'V92_KNOWLEDGE_SEED_INCOMPLETE: %', approved_count; end if;
end $$;

commit;
